class Solution {
public:
    int sumOfFlooredPairs(vector<int>& nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);

        vector<int> cnt(maxVal + 1, 0);
        for (int x : nums) cnt[x]++;

        vector<int> pref(maxVal + 2, 0);
        for (int i = 1; i <= maxVal + 1; ++i) {
            pref[i] = pref[i - 1] + cnt[i - 1];
        }

        long long ans = 0, MOD = 1000000007;
        for (int x = 1; x <= maxVal; ++x) {
            if (cnt[x] == 0) continue;
            long long currSum = 0;
            for (int k = 1; k * x <= maxVal; ++k) {
                int low = k * x;
                int high = min(maxVal, (k + 1) * x - 1);
                int countInRange = pref[high + 1] - pref[low];
                currSum = (currSum + (long long)k * countInRange) % MOD;
            }
            ans = (ans + (long long)cnt[x] * currSum) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int sumOfFlooredPairs(int[] nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = Math.max(maxVal, x);

        int[] cnt = new int[maxVal + 1];
        for (int x : nums) cnt[x]++;

        int[] pref = new int[maxVal + 2];
        for (int i = 1; i <= maxVal + 1; ++i) {
            pref[i] = pref[i - 1] + cnt[i - 1];
        }

        long ans = 0, MOD = 1_000_000_007L;
        for (int x = 1; x <= maxVal; ++x) {
            if (cnt[x] == 0) continue;
            long currSum = 0;
            for (int k = 1; k * x <= maxVal; ++k) {
                int low = k * x;
                int high = Math.min(maxVal, (k + 1) * x - 1);
                int countInRange = pref[high + 1] - pref[low];
                currSum = (currSum + (long)k * countInRange) % MOD;
            }
            ans = (ans + (long)cnt[x] * currSum) % MOD;
        }
        return (int)ans;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var sumOfFlooredPairs = function(nums) {
    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;

    const cnt = new Int32Array(maxVal + 1);
    for (const x of nums) cnt[x]++;

    const pref = new Int32Array(maxVal + 2);
    for (let i = 1; i <= maxVal + 1; ++i) {
        pref[i] = pref[i - 1] + cnt[i - 1];
    }

    const MOD = 1000000007n;
    let ans = 0n;

    for (let x = 1; x <= maxVal; ++x) {
        if (cnt[x] === 0) continue;
        let currSum = 0n;
        for (let k = 1; k * x <= maxVal; ++k) {
            const low = k * x;
            const high = Math.min(maxVal, (k + 1) * x - 1);
            const countInRange = BigInt(pref[high + 1] - pref[low]);
            currSum = (currSum + BigInt(k) * countInRange) % MOD;
        }
        ans = (ans + BigInt(cnt[x]) * currSum) % MOD;
    }
    return Number(ans);
};
